-- ============================================================================
-- SEDIMA Parc — complément du relevé de transport (RECAP TONNAGE HEBDOMMADAIRE.29.xlsx).
--
-- **Ce n'est pas une migration.** Écrit par `scripts/charger-releve-complement.mts` :
-- les seuls voyages postérieurs au 2026-09-17, dernière date du relevé en base.
-- 180 voyages du 2026-09-18 au 2026-09-30 — 483 t par le parc, 3558 t par les transporteurs.
-- Écartés : aucun.
--
-- Rejouable : `on conflict (numero) do nothing`.
-- ============================================================================

on conflict (numero) do nothing;

select mode, count(*) as voyages, sum(tonnage) as tonnes, min(date) as du, max(date) as au
  from releve_transport where date > '2026-09-17' group by mode;
